<div class="page-head"><div><h1>社員管理</h1><p class="muted">招待制アカウントを管理します。</p></div><a class="button" href="<?= e(url('admin')) ?>">管理トップ</a></div>
<section class="panel"><h2>社員を追加</h2><p class="muted">作成後、本人へ24時間有効のパスワード設定メールを送ります。</p><form method="post" action="<?= e(url('admin/users/create')) ?>" class="grid-form"><?= \App\Csrf::field() ?><label>氏名<input name="full_name" required></label><label>社員番号<input name="employee_code"></label><label>メールアドレス<input type="email" name="email" required></label><label>入社日<input type="date" name="hired_on"></label><label>権限<select name="role"><option value="employee">社員</option><option value="admin">管理者</option></select></label><button class="primary">作成して招待する</button></form></section>
<section class="panel"><h2>社員一覧</h2><div class="table-wrap"><table><thead><tr><th>氏名</th><th>社員番号</th><th>メール</th><th>権限</th><th>状態</th><th>操作</th></tr></thead><tbody><?php foreach($users as $user): ?><tr><td><?= e($user['full_name']) ?></td><td><?= e($user['employee_code'] ?: '—') ?></td><td><?= e($user['email']) ?></td><td><?= $user['role']==='admin' ? '管理者' : '社員' ?></td><td><?php $labels=['active'=>'有効','disabled'=>'無効','suspended'=>'休職中']; $active=$user['status']==='active'; ?><span class="tag"><?= e($labels[$user['status']] ?? $user['status']) ?></span></td><td><?php if((int)$user['id']!==\App\Auth::id()): ?><div class="row-actions"><form method="post" action="<?= e(url('admin/users/toggle')) ?>" data-confirm="状態を変更しますか？"><?= \App\Csrf::field() ?><input type="hidden" name="user_id" value="<?= (int)$user['id'] ?>"><button class="small <?= $active?'danger':'' ?>"><?= $active?'無効化':'有効化' ?></button></form><form method="post" action="<?= e(url('admin/users/force-logout')) ?>" data-confirm="この社員の全端末を強制ログアウトしますか？"><?= \App\Csrf::field() ?><input type="hidden" name="user_id" value="<?= (int)$user['id'] ?>"><button class="small">強制ログアウト</button></form></div><?php else: ?>自分<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
